// Lambda entry point: the same app as server.ts, behind a check of the secret header that
// CloudFront adds. Requests that bypass CloudFront via the API Gateway URL get 403 (#14).
import { timingSafeEqual } from 'node:crypto'
import { Hono } from 'hono'
import { handle } from 'hono/aws-lambda'
import { createApp } from './app.ts'
import { loadConfig } from './config.ts'
import { kraken } from './kraken.ts'
import { createDynamoClient, createStore } from './store.ts'

// Generated by Terraform and set on both CloudFront and the Lambda.
const originSecret = Buffer.from(process.env.ORIGIN_SECRET ?? '')
if (originSecret.length === 0) {
  throw new Error('ORIGIN_SECRET is required')
}

const config = loadConfig()
const app = new Hono()

app.use(async (c, next) => {
  const given = Buffer.from(c.req.header('x-origin-secret') ?? '')
  // Checked before any other work. Constant-time comparison, so timing reveals nothing.
  if (given.length !== originSecret.length || !timingSafeEqual(given, originSecret)) {
    return c.json({ error: { code: 'FORBIDDEN' } }, 403)
  }
  await next()
})

app.route(
  '/',
  createApp({
    prices: kraken,
    store: createStore(createDynamoClient(undefined), config.tableName),
    config,
  }),
)

export const handler = handle(app)
